import json

def mcp_world(tool: str, **params):
    """Call a world MCP tool (e.g. tools.mcp__world__api_search) and return the parsed result.

    tool: full tool name like 'mcp__world__api_search' or 'mcp__world__api_fetch'.
    Returns the tool output (raw JSON string) and prints a truncated preview.
    """
    import json as _json
    # find the actual MCP tool callable
    fn = None
    for prefix in (tool, "mcp__world__" + tool, "mcp__world_" + tool):
        try:
            fn = getattr(__builtins__, prefix, None)
        except Exception:
            fn = None
        if fn is None:
            try:
                import tools as t
                fn = getattr(t, prefix, None)
            except Exception:
                fn = None
        if fn is not None:
            break
    if fn is None:
        raise RuntimeError(f"mcp tool {tool!r} not reachable from tools namespace")
    out = fn(**params)
    return out

def search(params_json: str):
    """Run tools.mcp__world__api_search with a JSON string of params. Returns the raw result string."""
    import json as _json
    out = tools.mcp__world__api_search(**_json.loads(params_json))
    return out

