import json

def explore():
    """Stage 1: discover the world API surface. Searches several queries via tools.mcp__world__api_search, then prints compact endpoint list + hints. Returns concatenated raw results."""
    results = []
    for q in ["all", "spreadsheet", "capacity", "meeting", "calendar", "slack", "email", "cancel", "notify", "channel"]:
        try:
            out = tools.mcp__world__api_search({"query": q, "top_k": 20})
            s = json.dumps(out, default=str) if not isinstance(out, str) else out
            results.append(f"=== query={q!r} ===\n{s[:4000]}")
        except Exception as e:
            results.append(f"=== query={q!r} ERROR: {e}")
    return "\n".join(results)[:18000]

import json

def probe(q="spreadsheet capacity limits", k=5):
    """Probe how the world MCP tools accept arguments. Tries positional, single-dict, and kwarg forms of mcp__world__api_search/api_fetch. Prints every outcome; returns a compact report."""
    lines = []
    p1 = {"query": q, "top_k": k}
    p2 = (q, k)
    try:
        out = tools.mcp__world__api_search(p1)
        lines.append("pos-dict: " + (json.dumps(out, default=str)[:1500] if not isinstance(out, str) else out[:1500]))
    except Exception as e:
        lines.append(f"pos-dict ERR: {e}")
    try:
        out = tools.mcp__world__api_search(p2)
        lines.append("pos-tuple: " + (json.dumps(out, default=str)[:1500] if not isinstance(out, str) else out[:1500]))
    except Exception as e:
        lines.append(f"pos-tuple ERR: {e}")
    try:
        out = tools.mcp__world__api_search(query=q, top_k=k)
        lines.append("kw: " + (json.dumps(out, default=str)[:1500] if not isinstance(out, str) else out[:1500]))
    except Exception as e:
        lines.append(f"kw ERR: {e}")
    # maybe it is the mcp_world_tools lister from the tool list; try mcp__world__* names via search tool
    try:
        tools.mcp__world__tools()
        lines.append("mcp__world__tools: called ok (output suppressed)")
    except Exception as e:
        lines.append(f"mcp__world__tools ERR: {e}")
    return "\n".join(lines)

def world(q):
    """Wrapper: call tools.mcp__world__api_search with query=q, top_k=30 and return compact list of endpoint ids|methods|descriptions."""
    import json as _j
    r = tools.mcp__world__api_search(query=q, top_k=30)
    if isinstance(r, str):
        r = _j.loads(r) if r.strip().startswith(("{","[")) else {"raw": r}
    items = r.get("results", r if isinstance(r, list) else [])
    out = []
    for it in items:
        if isinstance(it, dict):
            out.append(f"{it.get('id')} | {it.get('method','')} | {it.get('description','')[:150]} | req: {it.get('request','')} | resp: {it.get('response','')[:200]}")
    return "\n".join(out) if out else _j.dumps(r, default=str)[:2500]

